for(const m of MODIFIERS)test('Chaos-aware ordinary inputs remain active and role-aware: '+m.id,()=>{const s=session('classic',8);applyChaos(s.sim,[m.id]);setChaosContext(s.sim,[m.id]);const before=s.sim.frogs.map(f=>({...f.body.getPosition()}));let moving=0;for(let frame=0;frame<900&&s.rules.phase==='playing';frame++){const state=tacticalState(s.rules.view(s.sim.tick));s.cs.forEach((c,i)=>{const f=s.sim.frogs[i],input=c.input(f,s.sim.tick,true,false,s.sim.frogChaos.trapped(f),s.sim,state,[m.id]);assert.ok([-1,0,1].includes(input.x)&&[-1,0,1].includes(input.y));assert.equal(typeof input.held,'boolean');if(input.x||input.y||input.held)moving++;});s.step();}assert.ok(moving>800,m.id);assert.ok(s.cs.every(c=>c.tactics.stats.decisions>10));assert.ok(s.cs.every(c=>c.diagnostics.errors===0));assert.ok(s.cs.some(c=>c.tactics.stats.pursuits>0));assert.ok(s.cs.some(c=>c.tactics.stats.evades>0));assert.ok(s.sim.frogs.every(f=>Number.isFinite(f.body.getPosition().x+f.body.getPosition().y)));assert.ok(s.sim.frogs.some((f,i)=>Math.hypot(f.body.getPosition().x-before[i].x,f.body.getPosition().y-before[i].y)>2));});
test('combined effective physics, size and tongue configuration are read, not independently retuned',()=>{const s=session('classic',2);for(const ids of [['moon_frogs','turbo_toads','tiny_trouble'],['butterfeet','windy_weather','balloon_bellies'],['mega_tongues','super_suckers','quick_licks']]as ModifierId[][]){applyChaos(s.sim,ids);setChaosContext(s.sim,ids);s.sim.step();const f=s.sim.frogs[0],p=chaosPhysics(s.sim,f);assert.equal(p.gravity,Math.max(.25,s.sim.tuning.gravity*Math.abs(f.body.getGravityScale())));assert.equal(p.pullRatio,s.sim.tuning.grapplePullAcceleration/48);assert.equal(p.lickRatio,s.sim.tuning.tongueSpeed/35);assert.deepEqual(chaosContext(s.sim).ids,ids);}applyChaos(s.sim,[]);setChaosContext(s.sim,[]);assert.equal(chaosPhysics(s.sim,s.sim.frogs[0]).active,false);});
test('Butterfeet counter-steers using actual active acceleration; Turbo changes speed and reach plans use actual radius',()=>{const{sim,nav}=makeCourse();applyChaos(sim,['butterfeet','turbo_toads','mega_frogs']);setChaosContext(sim,['butterfeet','turbo_toads','mega_frogs']);const f=sim.frogs[0];f.body.setLinearVelocity(Vec2(9,0));const p=chaosPhysics(sim,f);assert.equal(p.steering,sim.tuning.groundAcceleration);assert.ok(p.coast<p.steering/10);assert.equal(p.speed,9);for(const surface of navigationGraph(sim).surfaces)assert.ok(surface.left>=surface.a.x+sim.tuning.frogRadius);f.grounded=true;nav.setDestination({x:5,y:19});const input=nav.input(sim,0);assert.equal(input.x,-1);});
test('Magnet Mouths planning uses the same bounded assisted shot as real simulation; terrain still blocks it',()=>{const{sim}=makeCourse();applyChaos(sim,['magnet_mouths']);setChaosContext(sim,['magnet_mouths']);const f=sim.frogs[0],other=sim.frogs[1];f.body.setTransform(Vec2(4,10),0);other.body.setActive(true);other.body.setTransform(Vec2(9,11.3),0);assert.equal(ray(sim,f,1,0)?.body,other.body);const wall=sim.world.createBody(Vec2(6,10));wall.createFixture(Box(.1,2));assert.equal(ray(sim,f,1,0)?.body,wall);});
test('Sticky wall and ceiling crawling/charged release uses existing controls and actual surface tangent',()=>{for(const normal of[{x:1,y:0},{x:0,y:1}]){const{sim,nav}=makeCourse();applyChaos(sim,['sticky_frogs']);setChaosContext(sim,['sticky_frogs']);const f=sim.frogs[0],body=sim.world.createBody(Vec2(4,10));body.createFixture(Box(.2,4));f.body.setTransform(Vec2(4.65,10),0);const support=sim.stickyFrogs.support.bind(sim.stickyFrogs);sim.stickyFrogs.support=()=>({body,point:Vec2(4.2,10),out:Vec2(normal.x,normal.y),tangent:Vec2(-normal.y,normal.x)});nav.setDestination(normal.x?{x:4.65,y:4}:{x:12,y:10});const crawl=nav.input(sim,0);assert.equal(normal.x?crawl.y:crawl.x,normal.x?-1:1);assert.equal(crawl.held,false);nav.continueTo({x:f.body.getPosition().x+normal.x*5,y:f.body.getPosition().y+normal.y*5});assert.equal(nav.input(sim,0).held,true);sim.tick+=60;assert.equal(nav.input(sim,0).held,false);sim.stickyFrogs.support=support;}});
test('Pogo, inflation, bumper, first swap and gravity flip invalidate stale charge without changing velocity',()=>{for(const event of['pogoTick','balloonPopTick','bumperTick','swapTick','gravityFlipTick']as const){const{sim,nav}=makeCourse();applyChaos(sim,[event==='gravityFlipTick'?'gravity_flip':'pogo_panic']);setChaosContext(sim,[event==='gravityFlipTick'?'gravity_flip':'pogo_panic']);nav.input(sim,0);(nav as any).mode='charge';(nav as any).until=1000;const f=sim.frogs[0];f[event]=1;f.grounded=false;f.body.setLinearVelocity(Vec2(4,-14));sim.tick=1;const before={...f.body.getLinearVelocity()},input=nav.input(sim,0);assert.equal(input.held,false,event);assert.deepEqual({...f.body.getLinearVelocity()},before);}});
test('cracking platforms cost more, absent platforms disappear, and expiring Chaos restores baseline graph',()=>{const s=session('classic',2);applyChaos(s.sim,['crumble_time']);setChaosContext(s.sim,['crumble_time']);const state=s.sim.arenaChaos.capture()!;state.platforms[0].stage='cracking';state.platforms[0].clock=8;s.sim.arenaChaos.restore(state);s.sim.tick+=6;const b=navigationGraph(s.sim).surfaces.find(v=>Math.abs(v.body.getPosition().x-state.platforms[0].solid.x)<.01&&Math.abs(v.body.getPosition().y-state.platforms[0].solid.y)<.01)!.body;assert.ok(platformRisk(s.sim,b)>5);state.platforms[0].stage='absent';s.sim.arenaChaos.restore(state);s.sim.tick+=6;assert.ok(navigationGraph(s.sim).surfaces.every(s=>s.body!==b));applyChaos(s.sim,[]);setChaosContext(s.sim,[]);s.sim.tick+=6;assert.ok(navigationGraph(s.sim).surfaces.length>0);assert.equal(s.sim.arenaChaos.capture(),undefined);});
test('bubble escape keeps five genuine press/release edges while other modifiers are active',()=>{for(const ids of[['bubble_trouble','moon_frogs','windy_weather'],['bubble_trouble','mega_frogs','bumper_frogs']]as ModifierId[][]){const s=session('classic',8);applyChaos(s.sim,ids);setChaosContext(s.sim,ids);const state=s.sim.frogChaos.capture()!;state.bubbles=s.sim.frogs.map((f,i)=>({id:i,x:f.body.getPosition().x,y:16,born:0,captured:0,slot:i,presses:0}));s.sim.frogChaos.restore(state);const edges=Array(8).fill(0),held=Array(8).fill(false);for(let tick=0;tick<100;tick++){s.cs.forEach((c,i)=>{const f=s.sim.frogs[i],trapped=s.sim.frogChaos.trapped(f),input=c.input(f,s.sim.tick,true,false,trapped,s.sim,undefined,ids);if(trapped&&input.held&&!held[i])edges[i]++;held[i]=input.held;s.sim.setInput(i,input);});s.sim.step();}assert.deepEqual(edges,Array(8).fill(5));assert.ok(s.sim.frogs.every(f=>!s.sim.frogChaos.trapped(f)));}});
test('independent weighted votes use legal KEEP/ballots, one vote each, and remain seeded across reset',()=>{const counts=new Map<string,number>();for(let seed=1;seed<=30;seed++){const v=new ChaosVoting(true,seeded(seed),1000,1);v.active=['moon_frogs','mega_tongues','quick_licks'];v.open(0);const c=new CPUController(seed);assert.ok(v.choices.includes('moon_frogs'));c.vote(v,'cpu',['cpu'],0);c.vote(v,'cpu',['cpu'],900);c.vote(v,'cpu',['cpu'],999);assert.equal(v.votes.size,1);const chosen=v.votes.get('cpu')!;assert.ok(v.choices.includes(chosen));counts.set(chosen,(counts.get(chosen)??0)+1);}assert.ok(counts.size>=3);assert.ok(counts.has('moon_frogs'));const a=voteWeights(['mega_tongues','super_suckers'],[],1,{grapple:1.3,vertical:1,risk:1}),b=voteWeights(['mega_tongues','super_suckers'],['mega_tongues'],1,{grapple:1.3,vertical:1,risk:1});assert.ok(b[1]>a[1]);assert.ok(!eligibleModifierIds(['moon_frogs'],'classic','sunny-pond').includes('gravity_flip'));assert.ok(!eligibleModifierIds(['tiny_trouble'],'poison','sunny-pond').includes('mega_frogs'));});
test('all approved human gameplay, modifier physics, client visuals, input and viewport sources remain exact',()=>{const m=JSON.parse(readFileSync('docs/bot-c-preservation.json','utf8')),hash=(s:any)=>createHash('sha256').update(s).digest('hex');for(const[p,h]of Object.entries(m.protected))assert.equal(hash(readFileSync(p)),h,p);for(const[p,r]of Object.entries(m.files)as[string,any][]){assert.equal(hash(r.original),r.beforeSha256,p);assert.equal(hash(readFileSync(p)),r.afterSha256,p);}for(const p of['server/chaos/perception.ts','server/cpu.ts','server/navigation/navigator.ts','server/navigation/geometry.ts','server/strategy/tactics.ts'])assert.doesNotMatch(readFileSync(p,'utf8'),/setTransform|setPosition|setLinearVelocity|applyLinearImpulse|applyForce|\.infect\(|\.launch\(|\.fire\(/);});
test('real Sticky contact climbs a wall then jumps off using legitimate held/released action',()=>{const{sim,nav}=makeCourse();applyChaos(sim,['sticky_frogs']);setChaosContext(sim,['sticky_frogs']);const f=sim.frogs[0],wall=sim.world.createBody(Vec2(5,12));wall.createFixture(Box(.3,7));f.body.setTransform(Vec2(5.74,12),0);nav.setDestination({x:5.74,y:8});let attached=false,climbed=false,released=false;for(let i=0;i<180;i++){sim.setInput(0,nav.input(sim,0));sim.step();if(sim.stickyFrogs.support(f)?.body===wall)attached=true;if(f.body.getPosition().y<10)climbed=true;if(climbed){nav.continueTo({x:12,y:f.body.getPosition().y});if(f.stickyReleaseTick!==undefined){released=true;break;}}}assert.ok(attached);assert.ok(climbed);assert.ok(released);assert.ok(f.body.getLinearVelocity().x>0);});
test('modifier expiration clears AI-only sticky/route state without resetting the tactical role or altering the frog',()=>{const s=session('classic',2);applyChaos(s.sim,['sticky_frogs']);const c=s.cs[0],f=s.sim.frogs[0];c.input(f,0,true,false,false,s.sim,tacticalState(s.rules.view(0)),['sticky_frogs']);(c.navigation as any).stickyUntil=100;(c.navigation as any).mode='charge';applyChaos(s.sim,[]);const position={...f.body.getPosition()};c.input(f,1,true,false,false,s.sim,tacticalState(s.rules.view(1)),[]);assert.equal((c.navigation as any).stickyUntil,0);assert.deepEqual({...f.body.getPosition()},position);assert.notEqual(c.tactics.intent,'wait');});
test('all 20 modifiers activate/expire without AI leaks; KEEP renewal retains legal effect and baseline restoration',()=>{const s=session('classic',2);for(const m of MODIFIERS){applyChaos(s.sim,[m.id]);s.cs[0].input(s.sim.frogs[0],s.sim.tick,true,false,false,s.sim,tacticalState(s.rules.view(s.sim.tick)),[m.id]);applyChaos(s.sim,[]);s.sim.tick+=6;const input=s.cs[0].input(s.sim.frogs[0],s.sim.tick,true,false,false,s.sim,tacticalState(s.rules.view(s.sim.tick)),[]);assert.ok([-1,0,1].includes(input.x));assert.equal((s.cs[0].navigation as any).stickyUntil,0);assert.equal(chaosContext(s.sim).signature,'');assert.equal(s.cs[0].diagnostics.errors,0);}const v=new ChaosVoting(true,seeded(23),100,1);v.active=['sticky_frogs','mega_tongues','quick_licks'];v.open(0);assert.ok(v.vote('cpu','sticky_frogs',v.ballotId,['cpu'],99));v.advance(100,['cpu']);assert.deepEqual(v.active,['mega_tongues','quick_licks','sticky_frogs']);applyChaos(s.sim,v.active);setChaosContext(s.sim,v.active);assert.ok(s.sim.stickyFrogs.active);});
test('Moon rise accounts for actual free-flight drag and airborne braking differs from normal gravity',async()=>{const{jumpRise}=await import('../server/chaos/perception');const s=session('classic',2);applyChaos(s.sim,['moon_frogs']);setChaosContext(s.sim,['moon_frogs']);assert.ok(jumpRise(s.sim,s.sim.tuning.chargedJumpImpulse)<s.sim.tuning.chargedJumpImpulse**2/(2*s.sim.tuning.gravity));assert.ok(jumpRise(s.sim,18)>jumpRise(s.sim,9.5));});
